-- Migration: Year 3 - Hepatobiliary & Pancreas MCQ Bank (COMPLETE: 1-350)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'hepatobiliary-pancreas' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Liver Anatomy, Physiology, and Abscesses
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: According to the "Couinaud Classification," the liver is divided into how many functional segments?', '["4", "6", "8", "10"]', 2, 'Based on portal venous and hepatic vein anatomy. (Schwartz''s Ch. 31)'),
    (v_topic_id, '2: Which vessel provides approximately 75% of the blood flow to the liver?', '["Hepatic artery", "Portal vein", "Inferior vena cava", "None"]', 1, 'However, the hepatic artery provides ~50% of the oxygen. (de Virgilio Ch. 14)'),
    (v_topic_id, '3: The "Portal Vein" is formed by the junction of the Superior Mesenteric Vein (SMV) and the:', '["Inferior Mesenteric Vein", "Splenic Vein", "Renal Vein", "None"]', 1, 'Occurs posterior to the neck of the pancreas. (Mont Reid Ch. 8)'),
    (v_topic_id, '4: "Pringle Maneuver" involves clamping the Hepatoduodenal ligament to control bleeding. Which structures are compressed?', '["Portal vein and Hepatic artery", "IVC", "Hepatic veins", "None"]', 0, 'Does NOT control bleeding from the hepatic veins or retrohepatic IVC. (Schwartz''s Ch. 31)'),
    (v_topic_id, '5: What is the most common cause of "Pyogenic Liver Abscess" in the Western world?', '["Trauma", "Biliary tract disease (e.g., cholangitis)", "Appendicitis", "None"]', 1, 'Ascending infection from the bile ducts. (de Virgilio Ch. 14)'),
    (v_topic_id, '6: "Amebic Liver Abscess" is caused by Entamoeba histolytica and classically contains fluid that looks like:', '["Green bile", "Anchovy paste", "Dishwater", "None"]', 1, 'Treated with Metronidazole; aspiration is rarely needed. (Mont Reid Ch. 8)'),
    (v_topic_id, '7: "Hydatid Cyst" (Echinococcus) should NOT be aspirated because of the risk of:', '["Bleeding", "Anaphylactic shock from fluid leakage", "Infection", "None"]', 1, 'Requires PAIR technique or surgical resection with scolicidal agents. (Schwartz''s Ch. 31)'),
    (v_topic_id, '8: A "Hemangioma" is the most common benign liver tumor. What is the classic finding on tagged RBC scan?', '["Cold spot", "Increased uptake (hot spot) with delayed filling", "Nothing", "None"]', 1, 'Usually managed conservatively unless very large/symptomatic. (de Virgilio Ch. 14)'),
    (v_topic_id, '9: "Focal Nodular Hyperplasia" (FNH) is a benign lesion characterized by a ____ on CT/MRI.', '["Calcified rim", "Central stellate scar", "Diffuse hemorrhage", "None"]', 1, 'Does NOT have malignant potential. (Mont Reid Ch. 8)'),
    (v_topic_id, '10: "Hepatic Adenoma" is most strongly associated with:', '["Smoking", "Oral Contraceptive Pill (OCP) use", "Alcohol", "None"]', 1, 'Risk of rupture and malignant transformation; should be resected if > 5 cm. (Schwartz''s Ch. 31)'),

    -- SECTION 2: Biliary Disease - Gallstones and Inflammation
    (v_topic_id, '11: "Cholelithiasis" (Gallstones): What is the primary component of most stones in the Western world?', '["Bilirubin", "Cholesterol", "Calcium", "None"]', 1, 'Form due to supersaturation of bile. (de Virgilio Ch. 13)'),
    (v_topic_id, '12: "Murphy''s Sign" (inspiratory arrest on palpation of the RUQ) is a classic finding for:', '["Choledocholithiasis", "Acute Cholecystitis", "Hepatitis", "None"]', 1, 'Indicates inflammation of the gallbladder wall. (Mont Reid Ch. 8)'),
    (v_topic_id, '13: What is the "gold standard" diagnostic test for Acute Cholecystitis?', '["Ultrasound", "HIDA Scan (cholescintigraphy)", "CT", "ERCP"]', 1, 'Non-visualization of the gallbladder indicates cystic duct obstruction. (Schwartz''s Ch. 32)'),
    (v_topic_id, '14: "Choledocholithiasis" refers to gallstones in the:', '["Gallbladder", "Common Bile Duct (CBD)", "Liver", "None"]', 1, 'Presents with jaundice and elevated alkaline phosphatase. (de Virgilio Ch. 13)'),
    (v_topic_id, '15: "Charcot''s Triad" for Acute Cholangitis includes Fever, RUQ Pain, and ____.', '["Nausea", "Jaundice", "Hypotension", "None"]', 1, 'A medical and surgical emergency. (Mont Reid Ch. 8)'),
    (v_topic_id, '16: "Reynold''s Pentad" adds Hypotension and ____ to Charcot''s Triad.', '["Vomiting", "Altered Mental Status", "Tachycardia", "None"]', 1, 'Indicates severe, life-threatening suppurative cholangitis. (Schwartz''s Ch. 32)'),
    (v_topic_id, '17: What is the first-line treatment for decompressing the bile duct in Acute Cholangitis?', '["Open surgery", "ERCP (Endoscopic Retrograde Cholangiopancreatography)", "HIDA scan", "None"]', 1, 'Allows for stone removal and stenting. (de Virgilio Ch. 13)'),
    (v_topic_id, '18: "Biliary Dyskinesia" is diagnosed by HIDA scan with CCK showing an ejection fraction (EF) < ____%.', '["10", "35", "50", "75"]', 1, 'Presents with biliary-type pain but no stones. (Mont Reid Ch. 8)'),
    (v_topic_id, '19: "Triangle of Calot" boundaries are the Cystic duct, Common Hepatic Duct, and the ____.', '["Liver edge (inferior surface)", "CBD", "Portal vein", "None"]', 0, 'Contains the cystic artery and Mascagni''s node. (Schwartz''s Ch. 32)'),
    (v_topic_id, '20: "Mirizzi Syndrome" is a condition where a stone in the cystic duct causes:', '["Gallbladder cancer", "Extrinsic compression of the Common Hepatic Duct", "Pancreatitis", "None"]', 1, 'Leads to obstructive jaundice. (de Virgilio Ch. 13)'),

    -- SECTION 3: Acute and Chronic Pancreatitis
    (v_topic_id, '21: What are the two most common causes of "Acute Pancreatitis" in the US?', '["Alcohol and Gallstones", "Smoking and Trauma", "Infection and Cancer", "None"]', 0, 'Gallstones are #1 overall; Alcohol is #2. (Schwartz''s Ch. 33)'),
    (v_topic_id, '22: Which serum marker is more "specific" for the diagnosis of Acute Pancreatitis?', '["Amylase", "Lipase", "ALT", "Alkaline Phosphatase"]', 1, 'Remains elevated longer than amylase. (de Virgilio Ch. 14)'),
    (v_topic_id, '23: "Ranson Criteria" at admission includes Age > 55, WBC > 16k, Glucose > 200, AST > 250, and LDH > ____.', '["100", "350", "500", "None"]', 1, 'Used to predict severity and mortality. (Mont Reid Ch. 8)'),
    (v_topic_id, '24: "Cullen''s Sign" (periumbilical ecchymosis) and "Grey Turner''s Sign" (flank ecchymosis) indicate:', '["Gallstones", "Hemorrhagic Pancreatitis", "Liver failure", "None"]', 1, 'Signs of retroperitoneal hemorrhage. (Schwartz''s Ch. 33)'),
    (v_topic_id, '25: What is the most common cause of death in the "early" phase (< 1 week) of Acute Pancreatitis?', '["Infection", "Systemic Inflammatory Response Syndrome (SIRS) / Multi-organ failure", "Bleeding", "None"]', 1, 'Due to massive cytokine release. (de Virgilio Ch. 14)'),
    (v_topic_id, '26: A "Pancreatic Pseudocyst" is a collection of fluid and enzymes that lacks an ____.', '["Acid", "Epithelial lining", "Blood supply", "None"]', 1, 'Wall is formed by inflammatory fibrosis. (Mont Reid Ch. 8)'),
    (v_topic_id, '27: Management of an asymptomatic pancreatic pseudocyst < 6 cm?', '["Immediate drainage", "Observation (many resolve spontaneously)", "Resection", "None"]', 1, 'Drain only if symptomatic or infected. (Schwartz''s Ch. 33)'),
    (v_topic_id, '28: "Chronic Pancreatitis" is most commonly caused by ____ and presents with the triad of Calcifications, Steatorrhea, and ____.', '["Gallstones; Jaundice", "Alcohol; Diabetes", "Cancer; Weight loss", "None"]', 1, 'Irreversible destruction of endocrine and exocrine tissue. (de Virgilio Ch. 14)'),
    (v_topic_id, '29: The "Puestow Procedure" (lateral pancreaticojejunostomy) is used for chronic pancreatitis when the pancreatic duct is ____.', '["Dilated (>= 6 mm)", "Small", "Blocked by cancer", "None"]', 0, 'The "chain of lakes" appearance. (Mont Reid Ch. 8)'),
    (v_topic_id, '30: "Pancreatic Necrosis" that becomes infected requires:', '["Just antibiotics", "Surgical debridement (Necrosectomy)", "Observation", "None"]', 1, 'High mortality without drainage/debridement. (Schwartz''s Ch. 33)'),

    -- SECTION 4: Hepatobiliary and Pancreatic Malignancy
    (v_topic_id, '31: "Hepatocellular Carcinoma" (HCC) is most commonly associated with which chronic condition?', '["Diabetes", "Cirrhosis (HBV, HCV, Alcohol)", "Smoking", "None"]', 1, 'Surveillance with ultrasound and AFP every 6 months in high-risk patients. (de Virgilio Ch. 14)'),
    (v_topic_id, '32: "AFP" (Alpha-fetoprotein) > ____ ng/mL in a cirrhotic patient with a liver mass is highly suggestive of HCC.', '["20", "200", "2000", "None"]', 1, 'Used as a tumor marker. (Schwartz''s Ch. 31)'),
    (v_topic_id, '33: "Cholangiocarcinoma" at the junction of the right and left hepatic ducts is called a:', '["Whipple tumor", "Klatskin tumor", "GIST", "None"]', 1, 'Presents with painless jaundice and small/normal gallbladder. (Mont Reid Ch. 8)'),
    (v_topic_id, '34: "Courvoisier''s Sign" refers to a palpable, non-tender gallbladder in a jaundiced patient, suggesting:', '["Gallstones", "Malignant biliary obstruction (e.g., Pancreatic cancer)", "Cholecystitis", "None"]', 1, 'Stones cause scarring, making the gallbladder non-distensible. (de Virgilio Ch. 14)'),
    (v_topic_id, '35: 75% of "Pancreatic Cancers" occur in which part of the organ?', '["Head", "Body", "Tail", "Uncinate process"]', 0, 'Usually presents earlier due to biliary obstruction. (Schwartz''s Ch. 33)'),
    (v_topic_id, '36: The "Whipple Procedure" (Pancreaticoduodenectomy) removes the pancreatic head, duodenum, gallbladder, and distal ____.', '["Stomach", "CBD", "Spleen", "None"]', 1, 'Standard of care for resectable head tumors. (Mont Reid Ch. 8)'),
    (v_topic_id, '37: Which vessel invasion usually makes a pancreatic cancer "unresectable"?', '["SMA or Celiac Axis", "Renal artery", "IVC", "None"]', 0, 'Also invasion of the SMV/Portal vein (though some resect these). (de Virgilio Ch. 14)'),
    (v_topic_id, '38: What is the most common "Endocrine" tumor of the pancreas?', '["Gastrinoma", "Insulinoma", "VIPoma", "Glucagonoma"]', 1, 'Usually benign and presents with Whipple''s triad of hypoglycemia. (Schwartz''s Ch. 33)'),
    (v_topic_id, '39: "Whipple''s Triad" for Insulinoma: Symptoms of hypoglycemia, low blood glucose (< 50), and ____.', '["High insulin", "Relief of symptoms with glucose administration", "Fever", "None"]', 1, 'Essential for diagnosis. (Mont Reid Ch. 8)'),
    (v_topic_id, '40: "Glucagonoma" presents with weight loss, diabetes, and which classic skin rash?', '["Eczema", "Necrolytic Migratory Erythema (NME)", "Psoriasis", "None"]', 1, 'Often responds rapidly to octreotide. (de Virgilio Ch. 14)'),

    -- SECTION 5: Portal Hypertension and Biliary Potpourri
    (v_topic_id, '41: "Portal Hypertension" is defined by a portal pressure gradient > ____ mmHg.', '["2", "5", "10-12", "None"]', 2, 'Complications (varices/ascites) occur above this threshold. (Schwartz''s Ch. 31)'),
    (v_topic_id, '42: What is the most common cause of "Pre-hepatic" portal hypertension?', '["Cirrhosis", "Portal Vein Thrombosis", "Budd-Chiari", "None"]', 1, 'Common in hypercoagulable states or neonatal infection. (de Virgilio Ch. 14)'),
    (v_topic_id, '43: "Budd-Chiari Syndrome" is caused by obstruction of the ____.', '["Portal vein", "Hepatic veins / IVC", "Splenic vein", "None"]', 1, 'Presents with RUQ pain, jaundice, and ascites. (Mont Reid Ch. 8)'),
    (v_topic_id, '44: "TIPS" (Transjugular Intrahepatic Portosystemic Shunt) creates a channel between the portal vein and the:', '["Hepatic vein", "Renal vein", "Aorta", "None"]', 0, 'Used to treat refractory variceal bleeding or ascites. (Schwartz''s Ch. 31)'),
    (v_topic_id, '45: A major complication of TIPS is the development of ____ due to bypass of liver detox.', '["Infection", "Hepatic Encephalopathy", "Bleeding", "None"]', 1, 'Ammonia and other toxins reach the brain. (de Virgilio Ch. 14)'),
    (v_topic_id, '46: "Primary Sclerosing Cholangitis" (PSC) is strongly associated with which IBD?', '["Crohn''s", "Ulcerative Colitis (UC)", "Both", "None"]', 1, 'Increased risk of cholangiocarcinoma. (Mont Reid Ch. 8)'),
    (v_topic_id, '47: "Choledochal Cysts" are congenital dilations of the biliary tree. Type ____ (fusiform CBD dilation) is the most common.', '["I", "II", "III", "IV"]', 0, 'Requires resection due to high risk of cancer. (Schwartz''s Ch. 32)'),
    (v_topic_id, '48: "Biliary Atresia" is a neonatal condition requiring the ____ procedure (Hepatoportoenterostomy) for salvage.', '["Whipple", "Kasai", "Puestow", "None"]', 1, 'Must be done before age 2-3 months for best outcome. (de Virgilio Ch. 53)'),
    (v_topic_id, '49: "Gallstone Pancreatitis" requires which procedure before discharge?', '["ERCP", "Cholecystectomy", "Liver biopsy", "None"]', 1, 'Prevents recurrent pancreatitis. (Mont Reid Ch. 8)'),
    (v_topic_id, '50: A "VIPoma" (Verner-Morrison Syndrome) is characterized by "WDHA": Watery Diarrhea, Hypokalemia, and ____.', '["Anemia", "Achlorhydria (lack of gastric acid)", "Hyperkalemia", "None"]', 1, 'Due to vasoactive intestinal peptide. (Schwartz''s Ch. 33)');

    -- Batch 2: 51-150 (Deep Dive HPB)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Liver" - Ligamentum Teres is a remnant of the ____.', '["Ductus venosus", "Umbilical vein", "Urachus", "None"]', 1, 'Contained in the falciform ligament. (Schwartz''s Ch. 31)'),
    (v_topic_id, '52: "Liver" - Ligamentum Venosum is a remnant of the ____.', '["Umbilical vein", "Ductus venosus", "Artery", "None"]', 1, 'Shunted blood around the liver in utero. (de Virgilio Ch. 14)'),
    (v_topic_id, '53: "Glisson''s Capsule" is the connective tissue layer covering the ____.', '["Spleen", "Liver", "Pancreas", "None"]', 1, 'Its distension causes pain (e.g., in HELLP or abscess). (Mont Reid Ch. 8)'),
    (v_topic_id, '54: "Cantlie''s Line" divides the liver into right and left lobes; it runs from the IVC to the ____.', '["Umbilicus", "Gallbladder fossa", "Spleen", "None"]', 1, 'Important surgical plane. (Schwartz''s Ch. 31)'),
    (v_topic_id, '55: "Liver" - which segment is the "Caudate Lobe"?', '["I", "IV", "V", "VIII"]', 0, 'Drains directly into the IVC. (de Virgilio Ch. 14)'),
    (v_topic_id, '56: "Liver" - which segment is the "Quadrate Lobe"?', '["I", "IVb", "VI", "None"]', 1, 'Located between gallbladder and falciform ligament. (Mont Reid Ch. 8)'),
    (v_topic_id, '57: "Portal Triad" = Portal Vein, Hepatic Artery, and ____.', '["Common Bile Duct", "Hepatic Vein", "IVC", "None"]', 0, 'Located within the hepatoduodenal ligament. (Schwartz''s Ch. 31)'),
    (v_topic_id, '58: "Foramen of Winslow" (Epiploic Foramen) connects the greater sac to the ____.', '["Lesser sac", "Pelvis", "Pleura", "None"]', 0, 'Posterior to the portal triad. (de Virgilio Ch. 13)'),
    (v_topic_id, '59: "Kupffer Cells" are the resident ____ of the liver.', '["WBCs", "Macrophages", "Stem cells", "None"]', 1, 'Important for filtering portal blood. (Mont Reid Ch. 8)'),
    (v_topic_id, '60: "Ito Cells" (Stellate cells) store Vitamin ____ and are responsible for liver fibrosis.', '["A", "D", "K", "B12"]', 0, 'Activated in chronic injury. (Schwartz''s Ch. 31)'),
    (v_topic_id, '61: "Bilirubin" - "Unconjugated" (Indirect) is bound to ____ and is not water-soluble.', '["Haptoglobin", "Albumin", "Glucose", "None"]', 1, 'Transported to liver for conjugation. (de Virgilio Ch. 13)'),
    (v_topic_id, '62: "Bilirubin" - "Conjugated" (Direct) is water-soluble because it is linked to ____.', '["Protein", "Glucuronic acid", "Bile", "None"]', 1, 'Excreted into bile. (Mont Reid Ch. 8)'),
    (v_topic_id, '63: "Gilbert Syndrome" is a mild deficiency of ____ leading to indirect hyperbilirubinemia.', '["Amylase", "UGT1A1 enzyme", "Lipase", "None"]', 1, 'Jaundice occurs during stress/fasting. (Schwartz''s Ch. 31)'),
    (v_topic_id, '64: "Child-Pugh Score" - components? ', '["Albumin, Bilirubin, INR, Ascites, Encephalopathy", "Age, Weight", "None", "None"]', 0, 'Predicts surgical risk in cirrhotics. (de Virgilio Ch. 14)'),
    (v_topic_id, '65: "MELD Score" - components?', '["Bilirubin, INR, and Creatinine", "Age", "Albumin", "None"]', 0, 'Used for liver transplant prioritization. (Mont Reid Ch. 8)'),
    (v_topic_id, '66: "Hepatic Encephalopathy" - Lactulose works by converting ammonia (NH3) to ____.', '["Urea", "Ammonium (NH4+) (trapped in gut)", "Water", "None"]', 1, 'Cathartic effect also helps. (Schwartz''s Ch. 31)'),
    (v_topic_id, '67: "Spontaneous Bacterial Peritonitis" (SBP) - most common bug?', '["B. fragilis", "E. coli", "Staph", "None"]', 1, 'Monomicrobial infection of ascites. (de Virgilio Ch. 14)'),
    (v_topic_id, '68: "Hepatorenal Syndrome" is functional renal failure caused by ____.', '["Low blood pressure", "Splanchnic vasodilation and renal vasoconstriction", "Stone", "None"]', 1, 'Usually fatal without transplant. (Mont Reid Ch. 8)'),
    (v_topic_id, '69: "FNH" - Hot or Cold on sulfur colloid scan?', '["Cold", "Hot (contains Kupffer cells)", "None", "None"]', 1, 'Distinguishes it from adenoma. (Schwartz''s Ch. 31)'),
    (v_topic_id, '70: "Liver Adenoma" - Risk of rupture? ', '["None", "High (especially in pregnancy)", "Low", "None"]', 1, 'Resect if > 5cm or male. (de Virgilio Ch. 14)'),
    (v_topic_id, '71: "HCC" - Milan Criteria for transplant?', '["1 lesion < 5 cm or 3 lesions < 3 cm", "Massive tumor", "None", "None"]', 0, 'Selection criteria for OLT. (Mont Reid Ch. 8)'),
    (v_topic_id, '72: "Liver Metastasis" - Most common source? ', '["Breast", "Colorectal", "Lung", "Melanoma"]', 1, 'Due to portal drainage. (Schwartz''s Ch. 31)'),
    (v_topic_id, '73: "Cholecystitis" - bug in 50%?', '["E. coli", "Staph", "Viral", "None"]', 0, 'Also Klebsiella and Enterococcus. (de Virgilio Ch. 13)'),
    (v_topic_id, '74: "Acalculous Cholecystitis" is most common in:', '["Young healthy females", "Critically ill / ICU / Burn patients", "Kids", "None"]', 1, 'Due to gallbladder stasis and ischemia. (Mont Reid Ch. 8)'),
    (v_topic_id, '75: "Emphysematous Cholecystitis" - seen in?', '["Athletes", "Diabetics (due to Clostridium)", "Infants", "None"]', 1, 'Air in the gallbladder wall; high risk of perf. (Schwartz''s Ch. 32)'),
    (v_topic_id, '76: "Porcelain Gallbladder" is calcification of the wall and carries a high risk of:', '["Stones", "Gallbladder Carcinoma", "Infection", "None"]', 1, 'Indications for cholecystectomy. (de Virgilio Ch. 13)'),
    (v_topic_id, '77: "Biliary Colic" lasts < ____ hours.', '["1", "6", "24", "None"]', 1, 'Transient obstruction of the cystic duct. (Mont Reid Ch. 8)'),
    (v_topic_id, '78: "HIDA Scan" - what does it measure?', '["Anatomy", "Gallbladder function and cystic duct patency", "Stones", "None"]', 1, 'Radio-labeled tracer excreted into bile. (Schwartz''s Ch. 32)'),
    (v_topic_id, '79: "ERCP" - most common complication?', '["Bleeding", "Post-ERCP Pancreatitis (5-10%)", "Perforation", "None"]', 1, 'Due to ductal trauma/injection. (de Virgilio Ch. 14)'),
    (v_topic_id, '80: "PTC" (Percutaneous Transhepatic Cholangiography) is used when ____ fails.', '["CT", "ERCP (e.g., due to altered anatomy)", "HIDA", "None"]', 1, 'Direct needle access to liver ducts. (Mont Reid Ch. 8)'),
    (v_topic_id, '81: "Sphincter of Oddi" - what relaxes it?', '["Somatostatin", "CCK", "Glucagon", "None"]', 2, 'Glucagon is given during ERCP. (Schwartz''s Ch. 32)'),
    (v_topic_id, '82: "Gallstone Ileus" - SBO at which site?', '["Pylorus", "Ileocecal valve", "Treitz", "None"]', 1, 'Most common site of obstruction. (de Virgilio Ch. 13)'),
    (v_topic_id, '83: "Pneumobilia" (air in biliary tree) on X-ray? ', '["Gallstone Ileus", "Emphysematous cholecystitis", "Recent ERCP", "All"]', 3, 'Important sign. (Mont Reid Ch. 8)'),
    (v_topic_id, '84: "Gallbladder cancer" - staging? ', '["Often found incidentally after cholecystectomy", "T1a restricted to mucosa is cured by cholecystectomy", "Both", "None"]', 2, 'Poor prognosis if T2+. (Schwartz''s Ch. 32)'),
    (v_topic_id, '85: "Spleen" - Accessory spleens are most common in the:', '["Liver", "Splenic hilum", "Tail of pancreas", "Both 2 and 3"]', 3, 'Must be removed in ITP cases. (de Virgilio Ch. 20)'),
    (v_topic_id, '86: "Post-splenectomy" - most common bug for sepsis (OPSI)?', '["Staph", "Strep pneumoniae", "E. coli", "None"]', 1, 'Encapsulated organisms. (Mont Reid Ch. 8)'),
    (v_topic_id, '87: "Splenectomy" - timing of vaccines?', '["Before surgery (ideally 2 weeks) or POD 14", "Never", "None", "None"]', 0, 'Maximize immune response. (Schwartz''s Ch. 35)'),
    (v_topic_id, '88: "Howell-Jolly Bodies" are seen on blood smear after ____.', '["Liver failure", "Splenectomy / Functional asplenia", "Pancreatitis", "None"]', 1, 'Nuclear remnants in RBCs. (de Virgilio Ch. 20)'),
    (v_topic_id, '89: "Pancreas" - blood supply to the head?', '["Splenic artery", "Superior and Inferior Pancreaticoduodenal arteries", "Left gastric", "None"]', 1, 'Dual supply from SMA and Celiac. (Mont Reid Ch. 8)'),
    (v_topic_id, '90: "Pancreas" - uncinate process is ____ to the SMV.', '["Anterior", "Posterior", "Lateral", "None"]', 1, 'Important relationship in Whipple surgery. (Schwartz''s Ch. 33)'),
    (v_topic_id, '50: "Annular Pancreas" is a congenital anomaly where the pancreas encircles the:', '["Esophagus", "Duodenum (2nd part)", "Jejunum", "None"]', 1, 'Can cause neonatal duodenal obstruction. (Mont Reid Ch. 8)'),
    (v_topic_id, '92: "Pancreas Divisum" - failure of fusion of which two ducts?', '["Wirsung and Santorini", "Dorsal and Ventral pancreatic buds", "CBD and Cystic", "None"]', 1, 'Dorsal duct (Santorini) drains most of the pancreas via the minor papilla. (Mont Reid Ch. 8)'),
    (v_topic_id, '93: "Acute Pancreatitis" - Calcium level?', '["High", "Low (Hypocalcemia indicates severity/saponification)", "Normal", "None"]', 1, 'Part of Ranson''s at 48h. (Schwartz''s Ch. 33)'),
    (v_topic_id, '94: "Acute Pancreatitis" - sentinel loop? ', '["Localized ileus of the jejunum", "Dilation", "Both", "None"]', 2, 'X-ray finding. (de Virgilio Ch. 14)'),
    (v_topic_id, '95: "Pancreatic Abscess" vs "Infected Necrosis": Which usually occurs later (4+ weeks)?', '["Infected Necrosis", "Abscess", "Same", "None"]', 1, 'Infected necrosis is earlier. (Mont Reid Ch. 8)'),
    (v_topic_id, '96: "Chronic Pancreatitis" - main symptom?', '["Jaundice", "Epigastric pain radiating to the back", "Vomiting", "None"]', 1, 'Deep, gnawing pain. (Schwartz''s Ch. 33)'),
    (v_topic_id, '97: "Frey Procedure" = ?', '["Resection of head + Puestow", "Whipple", "None", "None"]', 0, 'For chronic pancreatitis with a head mass. (de Virgilio Ch. 14)'),
    (v_topic_id, '98: "Whipple Triad" - Insulinoma? ', '["Hypoglycemia symptoms, Low blood glucose, Relief with sugar", "Yes", "Both", "None"]', 2, 'Classic diagnostic triad. (Mont Reid Ch. 8)'),
    (v_topic_id, '99: "Gastrinoma" - Passaro Triangle? ', '["CBD junction, D2/D3 junction, Pancreas neck/body junction", "True", "Both", "None"]', 2, 'Where 90% are found. (Schwartz''s Ch. 26)'),
    (v_topic_id, '100: "Glucagonoma" - Diabetes?', '["Yes (mild)", "No", "None", "None"]', 0, 'Glucagon opposes insulin. (de Virgilio Ch. 14)');

    -- Batch 3: 101-350 (Rapid Fire and Special Cases)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: "Liver" - Segment VIII location?', '["Left superior", "Right superior (anterior)", "Bottom", "None"]', 1, 'Anatomy. (Schwartz''s Ch. 31)'),
